package com.vandorlabs.neoforge.trapdoor;

import com.google.gson.*;
import com.vandorlabs.neoforge.fluid.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Compare the final actual Source opening emitter, not its unrelated conservative voxel faces. */
public final class TrapdoorFluidSurfaceChecks {
    private static int checks;
    private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static NativeFluidRegions regions(JsonObject descriptor){var p=descriptor.getAsJsonArray("plane");return NativeFluidRegions.opening(p.get(0).getAsDouble(),p.get(1).getAsDouble(),p.get(2).getAsDouble(),p.get(3).getAsDouble(),p.get(4).getAsDouble(),descriptor.get("open").getAsBoolean(),descriptor.get("present").getAsInt(),descriptor.get("joined").getAsBoolean(),descriptor.get("height0").getAsDouble(),descriptor.get("height1").getAsDouble());}
    private static void bits(MessageDigest hash,long value){for(int n=56;n>=0;n-=8)hash.update((byte)(value>>>n));}private static void number(MessageDigest hash,double value){bits(hash,Double.doubleToRawLongBits(value));}private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte value:bytes)out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
    public static void main(String[] args)throws Exception{var physics=NativeFluidVolume.build(List.of(),NativeFluidVolume.SINGLE_SIDE);int cases=0,total=0;try(var lines=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();var own=regions(row.getAsJsonObject("own"));List<NativeFluidSurface.Surface> mesh=new ArrayList<>();for(int side=0;side<2;side++){var neighbors=new NativeFluidSurface.Neighbor[6];for(int n=0;n<6;n++){var data=row.getAsJsonArray("neighbors").get(n).getAsJsonObject();var matches=data.getAsJsonArray("matches").get(side).getAsJsonArray();neighbors[n]=new NativeFluidSurface.Neighbor(null,data.has("region")?regions(data.getAsJsonObject("region")):null,matches.get(0).getAsBoolean(),matches.get(1).getAsBoolean(),data.getAsJsonArray("hidden").get(side).getAsBoolean());}var h=row.getAsJsonArray("corners").get(side);NativeFluidSurface.Height height=null;if(!h.isJsonNull()){var corners=h.getAsJsonArray();double a=corners.get(0).getAsDouble(),b=corners.get(1).getAsDouble(),c=corners.get(2).getAsDouble(),d=corners.get(3).getAsDouble();height=(x,z)->NativeFluidSurface.height(a,b,c,d,x,z);}mesh.addAll(NativeFluidSurface.surfaces(physics,own,side,neighbors,height));}need(!physics.facesMaterialized(),"analytic opening renderer requested a Cartesian face graph");MessageDigest hash=MessageDigest.getInstance("SHA-256");bits(hash,mesh.size());for(var surface:mesh){bits(hash,surface.side);bits(hash,surface.axis);bits(hash,surface.boundary);number(hash,surface.nx);number(hash,surface.ny);number(hash,surface.nz);bits(hash,surface.vertices.size());for(var p:surface.vertices){number(hash,p.x);number(hash,p.y);number(hash,p.z);}}String actualHash=hex(hash.digest());need(mesh.size()==row.get("faces").getAsInt()&&actualHash.equals(row.get("hash").getAsString()),"actual final opening surface bits/order case="+cases+" basis="+row.get("basis")+" pair="+row.get("pair")+" neighbor="+row.get("neighbor")+" count="+mesh.size()+" expected="+row.get("faces")+" hash="+actualHash);total+=mesh.size();cases++;}}
        need(cases==(args.length>1?Integer.parseInt(args[1]):5184),"source final surface coverage");System.out.println("Native Trapdoor final fluid surfaces PASS cases="+cases+" faces="+total+" checks="+checks+" analytic/no Cartesian faces");}
}
